class Solution {
public:
    int minArraySum(vector<int>& nums, int k, int op1, int op2) {
        int n = nums.size();
        vector<vector<vector<int>>> memo(n, vector<vector<int>>(op1 + 1, vector<int>(op2 + 1, -1)));

        auto dp = [&](auto& self, int i, int o1, int o2) -> int {
            if (i == n) return 0;
            if (memo[i][o1][o2] != -1) return memo[i][o1][o2];

            int x = nums[i];
            int res = x + self(self, i + 1, o1, o2);

            if (o1 > 0) {
                res = min(res, (x + 1) / 2 + self(self, i + 1, o1 - 1, o2));
            }
            if (o2 > 0 && x >= k) {
                res = min(res, (x - k) + self(self, i + 1, o1, o2 - 1));
            }
            if (o1 > 0 && o2 > 0) {
                int v1 = (x + 1) / 2;
                if (v1 >= k) {
                    res = min(res, (v1 - k) + self(self, i + 1, o1 - 1, o2 - 1));
                }
                if (x >= k) {
                    int v2 = x - k;
                    res = min(res, (v2 + 1) / 2 + self(self, i + 1, o1 - 1, o2 - 1));
                }
            }
            return memo[i][o1][o2] = res;
        };

        return dp(dp, 0, op1, op2);
    }
};

class Solution {
    public int minArraySum(int[] nums, int k, int op1, int op2) {
        int n = nums.length;
        Integer[][][] memo = new Integer[n][op1 + 1][op2 + 1];
        return solve(nums, k, 0, op1, op2, memo);
    }

    private int solve(int[] nums, int k, int i, int o1, int o2, Integer[][][] memo) {
        if (i == nums.length) return 0;
        if (memo[i][o1][o2] != null) return memo[i][o1][o2];

        int x = nums[i];
        int res = x + solve(nums, k, i + 1, o1, o2, memo);

        if (o1 > 0) {
            res = Math.min(res, (x + 1) / 2 + solve(nums, k, i + 1, o1 - 1, o2, memo));
        }
        if (o2 > 0 && x >= k) {
            res = Math.min(res, (x - k) + solve(nums, k, i + 1, o1, o2 - 1, memo));
        }
        if (o1 > 0 && o2 > 0) {
            int v1 = (x + 1) / 2;
            if (v1 >= k) {
                res = Math.min(res, (v1 - k) + solve(nums, k, i + 1, o1 - 1, o2 - 1, memo));
            }
            if (x >= k) {
                int v2 = x - k;
                res = Math.min(res, (v2 + 1) / 2 + solve(nums, k, i + 1, o1 - 1, o2 - 1, memo));
            }
        }
        return memo[i][o1][o2] = res;
    }
}

